// Monta o lote para o Supabase a partir das linhas da aba Leads.
// chave = telefone (so digitos) + data_hora: nao muda se a linha mudar de lugar na planilha.
function texto(v) { return v == null ? '' : String(v).trim(); }
function digitos(v) { return texto(v).replace(/\D/g, ''); }
function dataBr(v) { // dd/MM/yyyy -> yyyy-MM-dd, ou null
  const m = texto(v).match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (!m) return null;
  const d = m[1].padStart(2, '0'), mes = m[2].padStart(2, '0');
  return m[3] + '-' + mes + '-' + d;
}
function dataHoraBr(v) { // dd/MM/yyyy HH:mm -> ISO com fuso de Sao Paulo, ou null
  const m = texto(v).match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:\s+(\d{1,2}):(\d{2}))?/);
  if (!m) return null;
  return m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0') + 'T' + (m[4] || '00').padStart(2, '0') + ':' + (m[5] || '00') + ':00-03:00';
}
const lote = [];
for (const item of $input.all()) {
  const r = item.json;
  const telefone = digitos(r.telefone);
  const dataHora = texto(r.data_hora);
  if (!telefone && !texto(r.nome)) continue; // linha vazia
  lote.push({
    chave: (telefone || 'sem-telefone') + '|' + (dataHora || ('linha-' + (r.row_number || ''))),
    registrado_em: dataHoraBr(dataHora),
    data_hora_texto: dataHora,
    nome: texto(r.nome).slice(0, 120),
    telefone: telefone,
    interesse: texto(r.interesse).slice(0, 60),
    renda_informada: texto(r.renda_informada).slice(0, 60),
    unidade_interesse: texto(r.unidade_interesse).slice(0, 40),
    visita_dia: dataBr(r.visita_dia),
    visita_periodo: texto(r.visita_periodo).slice(0, 20),
    resumo: texto(r.resumo).slice(0, 1000),
    status: texto(r.status).slice(0, 40),
    corretor: texto(r.corretor).slice(0, 80),
    origem: texto(r.origem).slice(0, 40)
  });
}
if (!lote.length) return [];
return [{ json: { lote, quantos: lote.length } }];
